#!/usr/bin/env python3
"""Render an audited Low-Range research run as one portable HTML file."""
import json
import pathlib
import sys

if len(sys.argv) not in (3, 4):
    raise SystemExit("Usage: render-low-range-report.py RUN_DIRECTORY OUTPUT.html [CROSSCHECK_DIRECTORY]")
root = pathlib.Path(sys.argv[1])
protocol = json.loads((root / "protocol.json").read_text())
result = json.loads((root / "results.json").read_text())
audit = json.loads((root / "audit.json").read_text())
sample = json.loads((root / "sample-audit.json").read_text())
expanded = root / "stratified-expanded.json"
stratified = json.loads((expanded if expanded.exists() else root / "stratified.json").read_text())
if result.get("status") != "completed" or audit.get("status") != "passed" or sample.get("status") != "passed":
    raise SystemExit("A completed and audited run is required")
if protocol.get("schema") != "cts-low-range-short-detail-24h-research-v1" or protocol["policy"]["tags"] != ["sh"]:
    raise SystemExit("A Short-only symbol/hour research run is required")
if stratified.get("ledgerSha256") != result.get("ledgerSha256"):
    raise SystemExit("Stratified data does not match the audited cell ledger")
crosscheck = None
if len(sys.argv) == 4:
    crossroot = pathlib.Path(sys.argv[3])
    crosscheck = {name: json.loads((crossroot / f"{name}.json").read_text()) for name in ("protocol", "results", "audit", "sample-audit")}
    if crosscheck["results"].get("status") != "completed" or crosscheck["audit"].get("status") != "passed" or crosscheck["sample-audit"].get("status") != "passed":
        raise SystemExit("Crosscheck must be completed and audited")
payload = json.dumps({"protocol": protocol, "result": result, "audit": audit, "sample": sample, "stratified": stratified, "crosscheck": crosscheck}, separators=(",", ":")).replace("<", "\\u003c")
page = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Low-Range Short · 20-symbol research</title><style>
:root{color-scheme:dark;--bg:#09101d;--surface:#121d30;--line:#29384d;--text:#eaf1fa;--muted:#a9bad0;--mint:#64e6ba;--blue:#7ab1ff;--red:#ff8b91;--amber:#f4c576}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% 0%,#183355 0,transparent 36%),var(--bg);font:14px/1.5 system-ui,-apple-system,Segoe UI,sans-serif;color:var(--text)}
main{max-width:1450px;margin:auto;padding:38px 24px 80px}h1{font-size:clamp(30px,4vw,48px);letter-spacing:-.04em;line-height:1.08;margin:10px 0 14px}h2{font-size:21px;letter-spacing:-.02em;margin:0 0 6px}h3{font-size:15px;margin:0 0 4px}.eyebrow{text-transform:uppercase;letter-spacing:.13em;font-weight:700;color:var(--mint);font-size:11px}.lede{max-width:850px;color:var(--muted);font-size:16px}.badge{display:inline-block;border:1px solid #608669;color:#bff5d6;border-radius:99px;padding:4px 9px;font-size:11px;font-weight:650}.warn{margin-top:22px;padding:15px 17px;background:#332b1c;border:1px solid #80683a;border-radius:12px;color:#ffe4ad}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:22px 0}.card,.panel{background:linear-gradient(155deg,#162237,#111b2c);border:1px solid var(--line);border-radius:15px;padding:18px}.metric{font-size:27px;font-weight:760;letter-spacing:-.04em;margin:5px 0}.label,.note{color:var(--muted);font-size:12px}.panels{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:14px 0}.panel{margin:14px 0}.panels .panel{margin:0}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;min-width:850px;font-variant-numeric:tabular-nums}th,td{padding:10px 9px;border-bottom:1px solid var(--line);text-align:right;white-space:nowrap}th{color:var(--muted);font-size:11px;font-weight:650;text-transform:uppercase;letter-spacing:.045em}td:first-child,th:first-child{text-align:left}tbody tr:hover{background:#1d2b41}.positive{color:var(--mint)}.negative{color:var(--red)}.barrow{display:grid;grid-template-columns:55px 1fr 75px;align-items:center;gap:8px;margin:10px 0}.track{height:12px;background:#26354a;border-radius:99px;overflow:hidden}.fill{height:100%;border-radius:99px;background:var(--mint)}.fill.neg{background:var(--red)}.barval{text-align:right;font-variant-numeric:tabular-nums}.heat{display:grid;gap:3px;min-width:960px;grid-template-columns:44px repeat(24,minmax(32px,1fr));align-items:stretch}.heat .axis{color:var(--muted);font-size:10px;text-align:center}.heat .cell{height:32px;border-radius:4px;display:grid;place-items:center;font-size:9px;color:#edf4fb;font-variant-numeric:tabular-nums}.smallheat{min-width:300px;width:100%;border-collapse:separate;border-spacing:4px}.smallheat th,.smallheat td{border:0;text-align:center;padding:9px}.smallheat th:first-child{text-align:left}.smallheat td{border-radius:6px}.legend{display:flex;gap:13px;align-items:center;color:var(--muted);font-size:11px;margin:10px 0}.dot{width:11px;height:11px;display:inline-block;border-radius:3px}.foot{color:var(--muted);font-size:12px;max-width:1050px}.code{font-family:ui-monospace,monospace;overflow-wrap:anywhere}.sub{margin:0 0 14px;color:var(--muted)}
@media(max-width:850px){main{padding:24px 14px 60px}.cards{grid-template-columns:repeat(2,1fr)}.panels{grid-template-columns:1fr}.metric{font-size:22px}}@media(max-width:450px){.cards{grid-template-columns:1fr 1fr}.card{padding:12px}}
</style></head><body><main>
<div class="eyebrow">CTS-A-O · Short research study</div><h1>Low-Range Short, step by step</h1>
<p class="lede">A 24-hour, 20-symbol retrospective study of cost-aware range techniques. The tables follow the Base-style screen, direction-specific validation and later candidate-tape outcomes separately.</p>
<span class="badge">Offline · completed · independently audited</span><div class="warn"><strong>Research evidence only.</strong> These are overlapping, unallocated candidate tapes; they are not account returns, funded orders, exchange fills or proof of live profitability. The source was examined in earlier work. The new indication is not enabled in the production engine.</div>
<div id="cards" class="cards"></div>
<section class="panel"><h2>Each step · 2 through 6</h2><p class="sub">Initial validation is measured at the start of the 24-hour observation. Later PF uses settled candidate records whose direction-specific gate passed at entry. Open records are shown separately.</p><div class="scroll"><table><thead><tr><th>Step</th><th>Cells / Base passed</th><th>Contexts validated</th><th>Validated %</th><th>History PF</th><th>Settled / held</th><th>Long / short</th><th>Later PF</th><th>Net return sum</th></tr></thead><tbody id="steps"></tbody></table></div></section>
<div class="panels"><section class="panel"><h2>Initial validation rate</h2><p class="sub">Passed direction contexts ÷ contexts attached to Base-passed cells.</p><div id="validationBars"></div></section><section class="panel"><h2>Later candidate returns</h2><p class="sub">Sum of settled unit returns, percentage points; no capital sizing.</p><div id="netBars"></div></section></div>
<section class="panel"><h2>24-hour heatmap</h2><p class="sub">Each cell is the sum of settled unit returns in the hour ending after its UTC label. Gray means no settled candidate. Hover for counts and PF.</p><div class="legend"><span><i class="dot" style="background:#ab4b58"></i> negative</span><span><i class="dot" style="background:#1e594d"></i> positive</span><span><i class="dot" style="background:#273449"></i> no close</span></div><div class="scroll"><div id="hours" class="heat"></div></div></section>
<section class="panel"><h2>Symbol × hour heatmap</h2><p class="sub">Select a step to see all 20 symbols by UTC hour. Color shows the summed net unit return; numbers are settled candidate records. Empty cells stay visible.</p><label>Target step <select id="stepChoice"><option>2</option><option>3</option><option>4</option><option>5</option><option>6</option></select></label><div class="scroll"><table id="symbolHeat" class="smallheat" style="min-width:1000px"></table></div></section>
<div class="panels"><section class="panel"><h2>Later PF by timeframe</h2><p class="sub">Independent completed-bar lanes, grouped by step. A dash means no settled candidate.</p><div class="scroll"><table id="tfHeat" class="smallheat"></table></div></section><section class="panel"><h2>Later PF for Short</h2><p class="sub">This follow-up includes the Short range only.</p><div class="scroll"><table id="rangeHeat" class="smallheat"></table></div></section></div>
<section class="panel"><h2>Later PF by SL ratio</h2><p class="sub">Each stop ratio applies to the net range before cost is added. Cells pool overlapping configurations; hover for the settled count and net return sum.</p><div class="scroll"><table id="slHeat" class="smallheat" style="min-width:940px"></table></div></section>
<section class="panel"><h2>Later PF by trailing gap</h2><p class="sub">Trailing variants are grouped by their effective gap after the minimum is applied. Several requested shares resolve to one identical protection cell.</p><div class="scroll"><table id="trailHeat" class="smallheat"></table></div></section>
<div class="panels"><section class="panel"><h2>Trend and breakout relations</h2><p class="sub">Later candidate PF for each separate relation mode. These overlapping identities are not independent experiments.</p><div class="scroll"><table id="relationHeat" class="smallheat"></table></div></section><section class="panel"><h2>Channel lookback</h2><p class="sub">Later candidate PF by lookback in completed bars.</p><div class="scroll"><table id="windowHeat" class="smallheat"></table></div></section></div>
<section class="panel"><h2>Relation detail</h2><p class="sub">Each row aggregates the five methods and three lookbacks. Selecting a winner on this already-examined window would be exploratory.</p><div class="scroll"><table><thead><tr><th>Step · relation</th><th>Cells / Base passed</th><th>Contexts validated</th><th>Validated %</th><th>History PF</th><th>Settled / held</th><th>Long / short</th><th>Later PF</th><th>Net return sum</th></tr></thead><tbody id="relations"></tbody></table></div></section>
<section class="panel"><h2>Technique detail</h2><p class="sub">All relation modes and lookbacks are aggregated here. Repeated or correlated configurations remain overlapping evidence.</p><div class="scroll"><table><thead><tr><th>Step · technique</th><th>Cells / Base passed</th><th>Contexts validated</th><th>Validated %</th><th>History PF</th><th>Settled / held</th><th>Long / short</th><th>Later PF</th><th>Net return sum</th></tr></thead><tbody id="methods"></tbody></table></div></section>
<section class="panel"><h2>Every symbol, each step</h2><p class="sub">100 lines: all 20 symbols at each target step. Counts represent overlapping candidate records, not independent orders. Historical post-Base validation was calculated across the universe, not separately per symbol.</p><div class="scroll"><table><thead><tr><th>Step · symbol</th><th>Settled / held</th><th>Long / short</th><th>Wins / losses</th><th>Later PF</th><th>Net return sum</th></tr></thead><tbody id="symbolRows"></tbody></table></div></section>
<section class="panel"><h2>Every symbol and hour</h2><p class="sub">2,400 lines, including hours without a close. Times mark the start of the UTC close-hour bin; held positions are shown in the symbol summary, not attributed to an hour.</p><details id="detailPanel"><summary>Open all 2,400 step × symbol × hour rows</summary><div class="scroll"><table><thead><tr><th>Step · symbol · UTC hour</th><th>Settled</th><th>Long / short</th><th>Wins / losses</th><th>Later PF</th><th>Net return sum</th></tr></thead><tbody id="detailRows"></tbody></table></div></details></section>
<section class="panel" id="crosscheckPanel"><h2>Earlier-window breakout check</h2><p class="sub" id="crosscheckNote"></p><div class="scroll"><table><thead><tr><th>Step · breakout, 15m</th><th>Cells / Base passed</th><th>Contexts validated</th><th>Validated %</th><th>History PF</th><th>Settled / held</th><th>Long / short</th><th>Later PF</th><th>Net return sum</th></tr></thead><tbody id="crosscheckRows"></tbody></table></div></section>
<section class="panel"><h2>Scope and method</h2><p class="foot">This standalone diagnostic deliberately studies 1m, 5m and 15m independent lanes. The engine's default Short minimum timeframe is 15m; a different floor must be configured to include its faster lanes. Combined timeframe lanes, trailing-only siblings, account coordination and venue execution were not part of this research run.</p><div id="methodology" class="foot"></div></section>
<section class="panel"><h2>Research context</h2><p class="foot">Independent evidence motivates the checks rather than certifying these particular settings. A 2026 BTC walk-forward preprint finds that selected gross-positive forecasts can lose after transaction costs, and that a cost-aware filter changed results in some specifications. A study of backtest overfitting explains why selecting from many alternatives on examined history can make later performance disappoint.</p><p class="foot"><a style="color:#9ec9ff" href="https://arxiv.org/abs/2606.00060">Bysik &amp; Ślepaczuk, Machine Learning-Based Bitcoin Trading Under Transaction Costs (2026)</a> · <a style="color:#9ec9ff" href="https://papers.ssrn.com/sol3/papers.cfm?abstract_id=2308659">Bailey et al., Effects of Backtest Overfitting on Out-of-Sample Performance (2014)</a></p></section>
<p class="foot">Calculations use completed bars, next-bar entries and conservative stop-before-target checks. Historical qualification and later candidate outcomes are different samples. Results do not include actual commissions, bid-ask spread, account funding, portfolio exposure, symbol-specific admission or exchange reconciliation.</p>
<script>const DATA=__DATA__;
const {protocol:p,result:r,audit:a,sample:sa,stratified:st,crosscheck:cross}=DATA; const steps=[2,3,4,5,6], n=(x,d=2)=>typeof x==='number'&&Number.isFinite(x)?x.toFixed(d):'—';
const pf=x=>x==='no-loss'?'No loss':n(x,2); const pct=x=>typeof x==='number'?n(x,2)+'%':'—'; const utc=x=>new Date(x).toISOString().replace('T',' ').slice(0,16)+' UTC';
const net=b=>100*(b.gp-b.gl); const sign=x=>x>1e-10?'positive':x< -1e-10?'negative':''; const hpf=b=>pf(b.historicalPf); const fpf=b=>pf(b.forwardPf);
const metric=(label,value,desc)=>`<div class="card"><div class="label">${label}</div><div class="metric">${value}</div><div class="note">${desc}</div></div>`;
const g=r.total; document.querySelector('#cards').innerHTML=metric('Post-Base-style validation',`${g.validated} / ${g.contexts}`,`${pct(g.validatedPct)} of direction contexts after Base`)+metric('Historical validated PF',hpf(g),'Pooled accepted history; neutral 1')+metric('Later candidate PF',fpf(g),`${g.settled.toLocaleString()} settled records; unallocated`)+metric('Distinct cells checked',g.cells.toLocaleString(),`${g.basePassed.toLocaleString()} passed Base`);
function row(label,b){let outcome=b.settled?`${n(net(b),2)} pp`:'—';return `<tr><td><strong>${label}</strong></td><td>${b.cells.toLocaleString()} / ${b.basePassed.toLocaleString()}</td><td>${b.validated} / ${b.contexts}</td><td>${pct(b.validatedPct)}</td><td>${hpf(b)}</td><td>${b.settled.toLocaleString()} / ${b.openAtEnd.toLocaleString()}</td><td>${b.long.toLocaleString()} / ${b.short.toLocaleString()}</td><td>${fpf(b)}</td><td class="${b.settled?sign(net(b)):''}">${outcome}</td></tr>`}
document.querySelector('#steps').innerHTML=steps.map(s=>row(s,r.byStep[String(s)])).join('');
function bars(target,values,formatter){const max=Math.max(...values.map(v=>Math.abs(v??0)),1e-9);document.querySelector(target).innerHTML=values.map((v,i)=>`<div class="barrow"><span>Step ${steps[i]}</span><div class="track"><div class="fill ${v<0?'neg':''}" style="width:${Math.min(100,100*Math.abs(v??0)/max)}%"></div></div><span class="barval">${formatter(v)}</span></div>`).join('')}
bars('#validationBars',steps.map(s=>r.byStep[String(s)].validatedPct),pct);bars('#netBars',steps.map(s=>r.byStep[String(s)].settled?net(r.byStep[String(s)]):null),x=>x===null?'—':n(x,2)+' pp');
function shade(value,count){if(!count)return '#273449';const strength=Math.min(.85,.18+Math.log1p(Math.abs(value))*0.12);return value>=0?`rgba(42,172,124,${strength})`:`rgba(225,76,89,${strength})`}
const hour=document.querySelector('#hours');hour.innerHTML='<div></div>'+Array.from({length:24},(_,i)=>`<div class="axis">${new Date(p.start+i*3600000).getUTCHours().toString().padStart(2,'0')}</div>`).join('')+steps.map(s=>`<div class="axis">${s}</div>`+Array.from({length:24},(_,i)=>{let b=r.byStepHour[`${s}|${p.start+i*3600000}`];let v=b?net(b):0;return `<div class="cell" style="background:${shade(v,b?.settled)}" title="${utc(p.start+i*3600000)} · ${b?.settled??0} closes · PF ${b?fpf(b):'—'} · net ${n(v,2)} pp">${b?.settled?n(v,1):'·'}</div>`}).join('')).join('');
function heat(selector,map,cols,names){document.querySelector(selector).innerHTML='<thead><tr><th>Step</th>'+names.map(x=>`<th>${x}</th>`).join('')+'</tr></thead><tbody>'+steps.map(s=>'<tr><th>'+s+'</th>'+cols.map(c=>{let b=map[`${s}|${c}`],v=b?.forwardPf;let color=typeof v==='number'?shade(v-1,b.settled):'#273449';return `<td style="background:${color}" title="${b?.settled??0} settled · net ${b?n(net(b),2):'—'} pp">${b?fpf(b):'—'}</td>`}).join('')+'</tr>').join('')+'</tbody>'}
heat('#tfHeat',r.byStepTf,[1,5,15],['1m','5m','15m']);heat('#rangeHeat',r.byStepRange,['sh'],['Short']);
const ratios=Array.from({length:13},(_,i)=>(i+2)/4);heat('#slHeat',st.byStepSl,ratios,ratios.map(x=>`${x}×`));heat('#trailHeat',st.byStepTrail,['plain','minimum','above-minimum'],['No trail','Minimum gap','Above minimum']);
heat('#relationHeat',st.byStepRelation,p.relations,p.relations);heat('#windowHeat',st.byStepWindow,p.windows,p.windows.map(x=>`${x} bars`));
document.querySelector('#relations').innerHTML=steps.flatMap(s=>p.relations.map(rel=>row(`${s} · ${rel}`,st.byStepRelation[`${s}|${rel}`]))).join('');
document.querySelector('#methods').innerHTML=steps.flatMap(s=>p.methods.map(m=>row(`${s} · ${m}`,r.byStepMethod[`${s}|${m}`]))).join('');
const empty={settled:0,openAtEnd:0,long:0,short:0,wins:0,losses:0,gp:0,gl:0,forwardPf:null};
function symbolRow(label,b,hour=false){return `<tr><td><strong>${label}</strong></td><td>${b.settled.toLocaleString()}${hour?'':` / ${b.openAtEnd.toLocaleString()}`}</td><td>${b.long.toLocaleString()} / ${b.short.toLocaleString()}</td><td>${b.wins.toLocaleString()} / ${b.losses.toLocaleString()}</td><td>${fpf(b)}</td><td class="${b.settled?sign(net(b)):''}">${b.settled?n(net(b),2)+' pp':'—'}</td></tr>`}
document.querySelector('#symbolRows').innerHTML=steps.flatMap(s=>p.symbols.map(sym=>symbolRow(`${s} · ${sym}`,r.byStepSymbol[`${s}|${sym}`]??empty))).join('');
let detailReady=false;document.querySelector('#detailPanel').addEventListener('toggle',function(){if(!this.open||detailReady)return;document.querySelector('#detailRows').innerHTML=steps.flatMap(s=>p.symbols.flatMap(sym=>Array.from({length:24},(_,i)=>{const t=p.start+i*3600000;return symbolRow(`${s} · ${sym} · ${utc(t)}`,r.byStepSymbolHour[`${s}|${sym}|${t}`]??empty,true)}))).join('');detailReady=true});
function symbolHeat(){const s=Number(document.querySelector('#stepChoice').value),target=document.querySelector('#symbolHeat');target.innerHTML='<thead><tr><th>Symbol</th>'+Array.from({length:24},(_,i)=>`<th>${new Date(p.start+i*3600000).getUTCHours().toString().padStart(2,'0')}</th>`).join('')+'</tr></thead><tbody>'+p.symbols.map(sym=>'<tr><th>'+sym+'</th>'+Array.from({length:24},(_,i)=>{const t=p.start+i*3600000,b=r.byStepSymbolHour[`${s}|${sym}|${t}`]??empty;return `<td style="background:${shade(net(b),b.settled)}" title="${sym} · ${utc(t)} · ${b.settled} closes · PF ${fpf(b)} · net ${n(net(b),2)} pp">${b.settled||'·'}</td>`}).join('')+'</tr>').join('')+'</tbody>'}document.querySelector('#stepChoice').addEventListener('change',symbolHeat);symbolHeat();
if(cross){let q=cross.protocol,z=cross.results;let detail=z.total.contexts?`${z.total.validated} / ${z.total.contexts} contexts validated (${pct(z.total.validatedPct)}).`:'No contexts were available for post-Base validation.';document.querySelector('#crosscheckNote').innerHTML=`These breakout groups were chosen after seeing the main result and re-evaluated on ${utc(q.start)} to ${utc(q.end)}. That period overlaps the main study's training history, so this is not an independent holdout. ${z.total.basePassed} / ${z.total.cells.toLocaleString()} cells passed Base. ${detail}`;document.querySelector('#crosscheckRows').innerHTML=[2,3].map(s=>row(String(s),z.byStep[String(s)])).join('')}else document.querySelector('#crosscheckPanel').innerHTML='';
const allPct=g.cells?pct(100*g.validated/(2*g.cells)):'—';
const hours=Array.from({length:24},(_,i)=>steps.reduce((x,s)=>{let b=r.byStepHour[`${s}|${p.start+i*3600000}`];if(b){x.gp+=b.gp;x.gl+=b.gl}return x},{gp:0,gl:0}));
const up=hours.filter(x=>x.gp>x.gl).length,down=hours.filter(x=>x.gp<x.gl).length,flat=24-up-down;
document.querySelector('#methodology').innerHTML=`<p><strong>Timing:</strong> indicator warm-up from ${utc(p.warm)}; initial evaluation ${utc(p.evalFrom)} to ${utc(p.start)}; later observation ${utc(p.start)} to ${utc(p.end)}. Across all overlapping candidates, ${up} hours were positive, ${down} negative and ${flat} flat or empty.</p><p><strong>Inventory:</strong> ${p.symbols.length} symbols (${p.symbols.join(', ')}); ${p.methods.length} methods × ${p.windows.length} lookbacks × ${p.relations.length} relation modes × ${p.tfs.length} lanes. ${p.requestedPerSignalLane} requested protection combinations resolve to ${p.distinctPerSignalLane} distinct cells per signal and lane after equal-distance floor deduplication. The ledger audit checked ${a.cells.toLocaleString()} cells and ${a.distinctConfigIds.toLocaleString()} unique identities. A separate selection-time recalculation checked ${sa.cellsRecomputed} stratified cells using only information available at that time.</p><p><strong>Denominators:</strong> ${g.validated} / ${g.contexts} (${pct(g.validatedPct)}) is conditional on a Base-passed cell. Against all ${2*g.cells} prospective cell-direction contexts, including those stopped at Base, it is ${allPct}. The latter is a coverage measure; those failed-Base contexts were not post-Base evaluated.</p><p><strong>Distances:</strong> one provisional step = ${n(p.policy.step*100,2)}% of price; modeled round-trip cost = ${n(p.policy.cost*100,2)}%. Target = cost + range; stop = cost + max(one step, range × stop ratio); trailing gap = cost + max(two steps, range × trail ratio). Each settled return deducts cost once.</p><p><strong>Limitations:</strong> multiple configs can represent the same market event; a 12/24/48-bar breakout already implies a six-bar breakout in the same direction. Initial validation PF pools overlapping context histories. Later decisions use direction-gate evaluation at candidate entry but omit symbol-specific admission and account/venue execution. Shadow positions can suppress later hypothetical candidates even when an entry would have been rejected. No positive hour or profitability is guaranteed.</p><p class="code">Feed SHA-256: ${p.hashes.feed}<br>Cell ledger SHA-256: ${r.ledgerSha256}<br>Source SHA-256: ${p.hashes.source}</p>`;
</script></main></body></html>'''
pathlib.Path(sys.argv[2]).write_text(page.replace("__DATA__", payload), encoding="utf-8")
